fn put64(out:&mut [u8],p:usize,x:i64){out[p..p+8].copy_from_slice(&x.to_le_bytes());}
#[no_mangle] pub unsafe extern "C" fn edn_vec_mpy1(raw:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if raw.is_null()||n<4||n>130{return -1}let v=unsafe{std::slice::from_raw_parts(raw,n)};let count=v[0];if !(1..=64).contains(&count)||n!=2+2*count as usize{return -1}let q=count as usize;let scale=v[n-1];if !(-1024..=1023).contains(&scale){return -1}let mut y=[0i64;64];for i in 0..q{y[i]=v[1+i];let x=v[1+q+i];if !(-1024..=1023).contains(&y[i])||!(-1024..=1023).contains(&x){return -1}}let bytes=8*q;if out.is_null()||cap<bytes{return -2}let output=unsafe{std::slice::from_raw_parts_mut(out,bytes)};for i in 0..q{y[i]+=(scale*v[1+q+i])>>15}for i in 0..q{put64(output,8*i,y[i])}bytes as i64}
